# Problem: #3105 Longest Strictly Increasing or Strictly Decreasing Subarray
# Language: python3
# Submission Result: Submission Sent (Check LeetCode Profile)
# Auto-generated by LeetCode Agent

class Solution:
    def longestMonotonicSubarray(self, nums: List[int]) -> int:

        incr, decr, ans = 1, 1,1
        prev = nums.pop(0)

        for num in nums:

            incr = incr * (num > prev) + 1
            decr = decr * (num < prev) + 1
            prev = num

            ans = max(ans, incr, decr)
            
        return ans